      "That convenience is also its limitation. A value of 130 mg/dL an hour after lunch is entirely normal; the same 130 mg/dL after a twelve-hour fast is prediabetes. Without knowing the meal timing, a mid-range random value cannot be interpreted, which is why RBS is a triage and emergency test rather than a screening test."
