        "question": "What does a high CRP mean?",
        "answer": "A high CRP means inflammation somewhere in the body \u2014 from infection, injury, surgery, autoimmune disease or, less commonly, malignancy. It does not say where. Values above 100 mg/L point strongly towards bacterial infection, while 10\u201340 mg/L is more typical of viral illness or active rheumatological disease."
