        "question": "How quickly does CRP fall after starting antibiotics?",
        "answer": "In a treatment that is working, CRP typically begins falling within 48 hours and drops by roughly half every day or two once the infection is controlled. A CRP that does not fall by day 3, or that rises again after falling, suggests the antibiotic is not covering the organism or that there is a collection needing drainage."
