      "Blood calcium is held within a very narrow range by parathyroid hormone, vitamin D and calcitonin, drawing on the skeleton as a reservoir. This is why serum calcium is a poor measure of dietary calcium intake or of bone health \u2014 a person can have advanced osteoporosis and a perfectly normal serum calcium, because the body maintains the blood level by taking calcium from bone.",
