        "question": "Can antacids cause magnesium deficiency?",
        "answer": "Proton pump inhibitors such as omeprazole and pantoprazole can, when taken for months to years, by reducing intestinal magnesium absorption. It is a well-documented effect that is frequently missed, partly because magnesium is not in routine panels. Recovery after stopping the drug can take several months."
