        "question": "Can too much magnesium be harmful?",
        "answer": "Yes, particularly in people with reduced kidney function taking magnesium-containing antacids or laxatives. Rising levels cause nausea, flushing, loss of deep tendon reflexes, low blood pressure and, at high levels, respiratory depression and cardiac arrest. In healthy kidneys, excess dietary magnesium is excreted efficiently."
