        "answer": "Mild deficiency is treated with oral magnesium salts, though these commonly cause diarrhoea which itself limits absorption. Severe or symptomatic deficiency, and deficiency with arrhythmia, is treated with intravenous magnesium in a monitored setting. The underlying cause \u2014 a diuretic, a proton pump inhibitor, alcohol, malabsorption \u2014 also has to be addressed."
