        "question": "What does protein in urine mean?",
        "answer": "Protein in urine can be transient \u2014 after fever, exercise or prolonged standing \u2014 or persistent, which indicates kidney damage. Any dipstick reading of 1+ or more should be quantified with a urine protein-to-creatinine ratio and repeated. Persistent proteinuria is one of the strongest predictors of progressive kidney disease."
