        "answer": "Painless visible blood in urine in an adult, particularly over the age of 40, should always be investigated \u2014 it can indicate a bladder or kidney tumour, and it is one of the most important findings in urology not to dismiss. It can also come from stones, infection or glomerular disease, but the serious causes must be excluded first."
