      "Prolactin is secreted by the anterior pituitary under continuous inhibition by dopamine from the hypothalamus. Anything that reduces dopamine \u2014 dopamine-blocking drugs, a pituitary stalk lesion, or a prolactin-secreting adenoma \u2014 raises prolactin. Raised prolactin in turn suppresses GnRH, which lowers LH, FSH, oestrogen and testosterone, producing infertility and menstrual disturbance in women and low libido and hypogonadism in men.",
