        "answer": "Macroprolactin is prolactin bound to an antibody, forming a large complex that standard assays measure but which is biologically inactive. It accounts for a meaningful share of apparently raised prolactin results, causes no symptoms and needs no treatment. Any unexplained hyperprolactinaemia should be screened for it before an MRI is arranged."
