        "answer": "Yes. Raised prolactin suppresses GnRH, which lowers LH and FSH and prevents normal ovulation in women and reduces testosterone and sperm production in men. It is a well-recognised and highly treatable cause of infertility, which is why prolactin is part of any standard fertility workup."
