        "answer": "It depends entirely on the cause. If a drug is responsible, the prescriber reviews it. If hypothyroidism is responsible, thyroxine corrects it. A prolactinoma is usually treated medically with cabergoline or bromocriptine, which lower prolactin and shrink the tumour effectively; surgery is needed only in a minority."
