    "slug": "beta-hcg",
    "title": "Beta hCG Test: Normal Range by Week and Pregnancy Levels",
    "metaDescription": "Beta hCG below 5 mIU/mL means not pregnant. Learn hCG levels by week of pregnancy, the 48-hour doubling rule, what a slow rise means.",
    "badge": "NABL Accredited lab (MC-6849) \u00b7 FREE HOME COLLECTION",
    "h1Title": "Beta hCG Test: Normal Levels by Week and What the Doubling Rate Means",
    "subtitle": "Beta hCG is the hormone produced by the developing placenta and is the basis of every pregnancy test. Below 5 mIU/mL means not pregnant, above 25 mIU/mL confirms pregnancy. In a healthy early pregnancy the level roughly doubles every 48 to 72 hours, and that rate of rise carries more information than any single value.",
    "price": "499",
    "oldPrice": "750",
    "discountPercent": "33% OFF",
    "parametersCount": "Test-Specific",
    "sampleType": "Serum / EDTA Blood",
    "fastingRequired": "No special preparation required.",
    "turnaroundTime": "Same Day (6\u201312 Hours)",
    "category": "Hormones & Fertility Panels",
    "overview": [
      "Human chorionic gonadotrophin is produced by the syncytiotrophoblast of the developing placenta from the moment of implantation, about 6 to 8 days after fertilisation. It maintains the corpus luteum and its progesterone output until the placenta takes over. A quantitative serum beta-hCG detects pregnancy earlier and far more precisely than a urine test, typically from about 8 to 11 days after ovulation.",
      "The single most useful feature of hCG in early pregnancy is not its absolute value but its rate of change. In a normal intrauterine pregnancy the level rises by at least 66% every 48 hours, and usually roughly doubles, until it plateaus around 8 to 11 weeks. A slower rise raises concern about ectopic pregnancy or a failing pregnancy; a fall suggests miscarriage or a resolving ectopic.",
      "hCG is also a tumour marker. It is markedly raised in gestational trophoblastic disease and in certain germ cell tumours of the testis and ovary, and is used both for diagnosis and for monitoring treatment in those settings."
    ],
    "whyImportant": [
      "Evaluates key clinical parameters for Beta-hCG (Pregnancy Test).",
      "Conducted at NABL Accredited super speciality laboratory (MC-6849).",
      "Digital PDF report delivered directly to your WhatsApp & Email."
    ],
    "faqs": [
      {
        "question": "What beta hCG level confirms pregnancy?",
        "answer": "Above 25 mIU/mL confirms pregnancy, below 5 mIU/mL means not pregnant, and values between 5 and 25 are equivocal and should be repeated after 48 hours. A serum test detects pregnancy about 8 to 11 days after ovulation, earlier than a urine test."
      },
      {
        "question": "How fast should hCG rise in early pregnancy?",
        "answer": "In a healthy early pregnancy hCG rises by at least 66% every 48 hours and usually roughly doubles, continuing until it plateaus around 8 to 11 weeks. A rise of less than 53% over 48 hours is abnormal and needs urgent evaluation for ectopic pregnancy or a failing pregnancy."
      },
      {
        "question": "Can a single hCG value tell me if my pregnancy is healthy?",
        "answer": "No. The normal range for any given week is enormously wide and overlaps heavily between weeks, so one value tells you very little. What matters is the rate of change across two samples 48 hours apart, and what the ultrasound shows once hCG is above the discriminatory zone."
      },
      {
        "question": "What hCG level should show a pregnancy on ultrasound?",
        "answer": "Above roughly 1,500 to 2,000 mIU/mL, an intrauterine gestational sac should be visible on transvaginal ultrasound. If hCG is above this discriminatory zone and no sac is seen inside the uterus, ectopic pregnancy must be actively excluded."
      },
      {
        "question": "What does a slow rising hCG mean?",
        "answer": "A rise of less than 53% in 48 hours suggests either an ectopic pregnancy or a pregnancy that is not developing normally. It needs prompt assessment with transvaginal ultrasound and repeat testing, because an untreated ectopic pregnancy can rupture and become life-threatening."
      },
      {
        "question": "How early can a blood pregnancy test detect pregnancy?",
        "answer": "About 8 to 11 days after ovulation, or roughly 3 to 4 days before a missed period. This is several days earlier than most urine tests, which typically need hCG above 20 to 25 mIU/mL. A very early negative does not exclude pregnancy and should be repeated if the period does not arrive."
      },
      {
        "question": "Can hCG be falsely positive?",
        "answer": "Yes. An hCG trigger injection used in fertility treatment produces a positive result for up to 10 days. Rare heterophile antibodies can cause a persistently positive serum result with a negative urine test \u2014 an important distinction, because such false positives have led to unnecessary chemotherapy for suspected trophoblastic disease."
      },
      {
        "question": "What does very high hCG mean?",
        "answer": "Higher than expected for dates suggests a multiple pregnancy, a more advanced gestation than calculated, or gestational trophoblastic disease. A very high hCG with severe vomiting and an abnormal ultrasound raises the possibility of a molar pregnancy, which needs specialist management and follow-up until hCG reaches zero."
      },
      {
        "question": "How long does hCG take to become negative after a miscarriage?",
        "answer": "Typically two to six weeks, depending on how high the level was to begin with. Serial measurements are followed until hCG falls below 5 mIU/mL, which confirms complete resolution. A plateau or rise instead of a fall requires evaluation for retained tissue or trophoblastic disease."
      },
      {
        "question": "Do I need to fast for a beta hCG test?",
        "answer": "No, fasting is not required and the test can be done at any time of day. For serial monitoring, take the samples exactly 48 hours apart at roughly the same time, and use the same laboratory each time so the values are directly comparable."
      }
    ],
