      "Citrullination is a normal post-translational modification in which arginine residues are converted to citrulline. In people genetically predisposed to rheumatoid arthritis \u2014 particularly those carrying the shared epitope HLA-DRB1 alleles \u2014 the immune system loses tolerance to citrullinated proteins and produces antibodies against them. These are measured as anti-CCP.",
      "The specificity is what makes the test valuable. At around 95%, a positive anti-CCP in a patient with joint symptoms is highly likely to mean rheumatoid arthritis, whereas rheumatoid factor is positive in many other conditions and in a meaningful proportion of healthy older people. Sensitivity is comparable to rheumatoid factor at roughly 70%, so a negative result does not exclude the disease.",
      "Anti-CCP also carries prognostic weight. Patients who are anti-CCP positive, and particularly those with high titres, develop more erosive joint damage and more extra-articular disease. Because early aggressive treatment prevents irreversible damage, a positive anti-CCP in early arthritis is a strong argument for starting disease-modifying therapy without delay. It can also be detectable years before the first symptom appears."
