      "Its clinical use is narrow but real. In metastatic breast cancer, serial CA 15-3 measurements provide an inexpensive way to track whether treatment is working, particularly when disease is difficult to measure on imaging \u2014 bone-predominant metastases, for example. A falling level supports response and a consistently rising level suggests progression, usually prompting reassessment with imaging.",
