        "question": "Why did my CA 15-3 rise after starting chemotherapy?",
        "answer": "A transient rise in the first four to six weeks of chemotherapy is a recognised phenomenon caused by tumour cells breaking down and releasing their contents. It does not indicate treatment failure, and changing treatment on the basis of it is a well-described error \u2014 the trend over the following weeks is what matters."
