    "category": "Oncology & Tumor Markers",
    "overview": [
      "The same hormone that confirms pregnancy serves as one of oncology's most useful tumour markers. hCG is produced by trophoblastic tissue, and tumours containing syncytiotrophoblastic elements \u2014 choriocarcinoma, embryonal carcinoma, and a proportion of seminomas \u2014 secrete it into the circulation.",
      "In testicular cancer, beta-hCG is measured with AFP and LDH before orchidectomy and again afterwards. The three together define the risk group under the IGCCCG classification, which determines the intensity of chemotherapy. The rate at which they fall after treatment is itself prognostic: hCG has a half-life of 24 to 36 hours, and a slower than expected fall indicates residual disease.",
      "In gestational trophoblastic disease, hCG is the entire basis of management. After evacuation of a hydatidiform mole, hCG is followed to undetectable levels and then monitored for months; a plateau or rise defines gestational trophoblastic neoplasia and triggers chemotherapy. This is one of the few cancers where a blood test rather than imaging or biopsy drives the decision to treat."
    ],
    "whyImportant": [
      "Evaluates key clinical parameters for Beta-hCG as a Tumour Marker.",
      "Conducted at NABL Accredited super speciality laboratory (MC-6849).",
      "Digital PDF report delivered directly to your WhatsApp & Email."
    ],
    "faqs": [
      {
        "question": "What is a normal beta-hCG in a man?",
        "answer": "Below 5 mIU/mL. Any detectable beta-hCG in a man is abnormal and warrants investigation, most importantly a testicular examination and ultrasound to look for a germ cell tumour. Marijuana use and certain medications have occasionally been implicated but should not be assumed."
      },
      {
        "question": "Why is beta-hCG used in testicular cancer?",
        "answer": "Because tumours containing syncytiotrophoblastic elements secrete it. Measured with AFP and LDH before and after orchidectomy, it defines the risk group that determines chemotherapy intensity, and the rate at which it falls afterwards is itself an important prognostic indicator."
      },
      {
        "question": "Can beta-hCG be normal in testicular cancer?",
        "answer": "Yes. Pure seminoma raises hCG in only 15 to 20% of cases, and some non-seminomatous tumours produce only AFP or neither marker. A normal beta-hCG never removes the need for orchidectomy and histological examination when a testicular mass is present."
      },
      {
        "question": "How is hCG used after a molar pregnancy?",
        "answer": "It is followed serially until undetectable and then monitored for several months. A plateau or rise in hCG defines gestational trophoblastic neoplasia and is an indication to start chemotherapy \u2014 one of very few cancers where a blood test alone, without biopsy or imaging, drives the decision to treat."
      },
      {
        "question": "What does a very high hCG above 100,000 mean?",
        "answer": "In a woman, it suggests a molar pregnancy or choriocarcinoma. In a man, it suggests a germ cell tumour with choriocarcinomatous elements. Both need urgent specialist assessment. Very high levels can also cause hyperthyroidism, because hCG weakly stimulates the TSH receptor."
      },
      {
        "question": "Can beta-hCG be raised in a postmenopausal woman without cancer?",
        "answer": "Yes. The pituitary produces small amounts of hCG after menopause, and levels up to about 14 mIU/mL can be physiological. A mildly raised hCG in a postmenopausal woman with no other findings does not automatically indicate malignancy, and a suppression test can clarify the source."
      },
      {
        "question": "Do I need to fast for a beta-hCG tumour marker test?",
        "answer": "No, fasting is not required. Request a quantitative serum beta-hCG rather than a qualitative urine pregnancy test, and ensure AFP and LDH are measured on the same sample if germ cell tumour staging is the purpose."
      },
      {
        "question": "How fast should hCG fall after treatment?",
        "answer": "hCG has a half-life of 24 to 36 hours, so it should fall rapidly and predictably during effective treatment. A slower than expected decline indicates residual disease and is an adverse prognostic sign that may prompt intensification of chemotherapy."
      },
      {
        "question": "Can a false positive hCG lead to unnecessary treatment?",
        "answer": "Yes, and it is a documented problem. Rare heterophile antibodies can cause a persistently positive serum hCG with no tumour present, and cases of unnecessary chemotherapy and even surgery have been reported. A urine hCG, which is unaffected by these antibodies, resolves the question quickly."
      },
      {
        "question": "Does hCG cause gynaecomastia in men?",
        "answer": "It can. hCG stimulates testicular oestrogen production, and an hCG-secreting germ cell tumour can present with breast enlargement before the testicular mass is noticed. New gynaecomastia in a young man is a reason to examine the testes and consider hCG and AFP measurement."
      }
    ],
