    "overview": [
      "Creatine kinase exists as three isoenzymes: CK-MM in skeletal muscle, CK-BB in brain, and CK-MB, which makes up 15\u201320% of cardiac muscle CK and only 1\u20133% of skeletal muscle CK. That enrichment is what made CK-MB the cardiac marker of choice before troponin assays became available.",
      "Troponin has superseded it because troponin is more cardiac-specific and more sensitive. CK-MB is present in skeletal muscle, so any significant muscle injury \u2014 trauma, intramuscular injection, rhabdomyolysis, seizure, marathon running \u2014 raises it. The relative index, CK-MB divided by total CK and multiplied by 100, helps distinguish cardiac from skeletal muscle origin: above 2.5% favours cardiac.",
      "Where CK-MB retains genuine value is its kinetics. It rises within 4 to 6 hours, peaks at 18 to 24 hours and returns to normal within 48 to 72 hours, whereas troponin stays raised for up to two weeks. This makes CK-MB useful for detecting a second infarction a few days after the first, and for quantifying periprocedural myocardial injury after angioplasty or cardiac surgery."
    ],
