        "question": "Should CK-MB be ordered along with troponin?",
        "answer": "Not routinely. In a standard chest pain assessment where high-sensitivity troponin is available, adding CK-MB adds cost without adding diagnostic information. It should be reserved for specific questions \u2014 suspected reinfarction, or quantifying periprocedural injury."
