        "question": "What does a high total CK with a normal relative index mean?",
        "answer": "It points to skeletal muscle rather than heart as the source \u2014 trauma, intense exercise, an intramuscular injection, a seizure, or a muscle disease. Very high total CK with dark urine suggests rhabdomyolysis, which threatens the kidneys and needs urgent assessment."
