      "This is why the ratio matters more than either absolute value. Both free kappa and free lambda rise together in kidney impairment, since they are cleared renally, and both rise in polyclonal states such as infection and autoimmune disease. Only a clonal process shifts the ratio. A patient can have both values within the reference interval and still have an abnormal ratio indicating a clone.",
