        "question": "How does kidney disease affect free light chain results?",
        "answer": "Light chains are cleared by the kidneys, so both rise when eGFR falls. Kappa is normally cleared faster than lambda, so renal impairment shifts the ratio upward. Applying the standard reference range in someone with kidney disease will misread a normal ratio as a kappa clone, which is why a separate renal range exists."
