        "answer": "An involved-to-uninvolved free light chain ratio of 100 or more, with the involved light chain above 100 mg/L, is one of the myeloma-defining biomarkers under current international criteria. It indicates a high risk of imminent organ damage and warrants treatment even without hypercalcaemia, renal impairment, anaemia or bone lesions."
