        "answer": "In light chain only disease, where there is no measurable M-protein, the free light chain level and the ratio are the primary response measures. In AL amyloidosis, the difference between the involved and uninvolved light chains \u2014 the dFLC \u2014 is followed, with a value below 10 mg/L defining a very good partial response."
