        "question": "Do I still need SPEP if free light chains are normal?",
        "answer": "Yes. Free light chains detect light chain disease exceptionally well but do not detect intact immunoglobulin monoclonal proteins as reliably as SPEP and immunofixation. All three together give a negative predictive value above 99%, which no single test achieves."
