    "category": "Protein Disorders & Electrophoresis",
    "overview": [
      "Urine protein electrophoresis separates the proteins in urine by charge, and urine immunofixation then identifies whether any band present is monoclonal and which light chain type it is. Monoclonal free light chains in urine are historically called Bence Jones protein, after the physician who described their unusual heat precipitation behaviour in 1847.",
      "The most important practical point is that a routine urine dipstick cannot detect them. Dipstick protein pads react to albumin and are almost blind to light chains, so a patient can have grams of light chain in the urine with a dipstick reading trace or negative. Relying on a urine routine to exclude myeloma-related kidney disease is a well-recognised and consequential error.",
      "UPEP also describes the pattern of proteinuria. A predominantly albumin band indicates glomerular disease. Low molecular weight proteins predominating indicates tubular damage. A mixed pattern suggests both. In monoclonal gammopathy, the pattern helps distinguish cast nephropathy, where light chains predominate, from AL amyloidosis and light chain deposition disease, where albuminuria is prominent because the glomerulus is affected."
    ],
    "whyImportant": [
      "Evaluates key clinical parameters for Urine Protein Electrophoresis (UPEP).",
      "Conducted at NABL Accredited super speciality laboratory (MC-6849).",
      "Digital PDF report delivered directly to your WhatsApp & Email."
    ],
    "faqs": [
      {
        "question": "What is Bence Jones protein?",
        "answer": "Monoclonal free light chains excreted in urine by an abnormal plasma cell clone. They are named after Henry Bence Jones, who described their unusual behaviour on heating in 1847. They are detected by urine protein electrophoresis with immunofixation, not by a routine urine test."
      },
      {
        "question": "Why does a urine dipstick miss light chains?",
        "answer": "Because the protein pad on a dipstick reacts to albumin and is almost blind to light chains. A patient can have grams of light chain protein in the urine with a dipstick reading trace or negative. Relying on a urine routine to exclude myeloma-related kidney disease is a serious and well-recognised error."
      },
      {
        "question": "How do I collect a 24-hour urine sample correctly?",
        "answer": "Discard the first sample on the morning you start. Collect every subsequent sample including the first one the following morning, in the container provided. Keep it refrigerated throughout and record the total volume, which the laboratory needs to calculate daily excretion."
      },
      {
        "question": "Is a spot urine sample acceptable instead of 24 hours?",
        "answer": "An early morning sample with a protein-to-creatinine ratio is acceptable for many purposes and is far easier to collect correctly. A 24-hour collection remains the standard for quantifying light chain excretion for staging and treatment monitoring, where precise daily figures matter."
      },
      {
        "question": "Can I have myeloma with a normal urine test?",
        "answer": "Yes, in two ways. A routine urine dipstick misses light chains entirely. And even a proper UPEP can be negative in intact immunoglobulin myeloma, where the monoclonal protein is too large to pass into urine. This is why the complete screen requires serum studies as well."
      },
      {
        "question": "What is cast nephropathy?",
        "answer": "It is acute kidney injury caused by free light chains precipitating with Tamm-Horsfall protein inside the kidney tubules, forming obstructing casts. It is the commonest cause of kidney failure in myeloma and is a medical emergency requiring urgent treatment to reduce the light chain load."
      },
      {
        "question": "What does an albumin-predominant pattern mean in a myeloma patient?",
        "answer": "It suggests the glomerulus is affected rather than the tubules, which points towards AL amyloidosis or light chain deposition disease rather than cast nephropathy. This distinction usually requires a kidney or fat pad biopsy with Congo red staining to confirm, and it changes management substantially."
      },
      {
        "question": "Is UPEP or serum free light chains better?",
        "answer": "Serum free light chains are more sensitive and detect smaller clones, and they are also easier to collect. UPEP with immunofixation remains valuable for quantifying light chain excretion, characterising the pattern of kidney damage, and confirming Bence Jones proteinuria. Current guidance recommends both as part of a complete assessment."
      },
      {
        "question": "Do I need to fast for a urine protein electrophoresis?",
        "answer": "No, fasting is not required. What matters is collecting the sample correctly \u2014 a complete 24-hour collection kept refrigerated with the total volume recorded, or a properly collected early morning sample if a spot ratio is being used instead."
      },
      {
        "question": "How is UPEP used to monitor myeloma treatment?",
        "answer": "In light chain disease, 24-hour urine light chain excretion is one of the measures used to assess response, alongside serum free light chains. A fall of more than 90%, or to below 200 mg per 24 hours, defines a very good partial response, and disappearance of the band on immunofixation is part of the complete response definition."
      }
    ],
