    "overview": [
      "Antibody testing is how dengue is diagnosed once the NS1 window has passed. IgM becomes detectable from about day 5 of fever, peaks around day 10 to 14, and can persist for two to three months. IgG appears later in a first infection, from around day 14, and persists for life.",
      "In a second dengue infection with a different serotype, the pattern changes. Memory B cells produce IgG rapidly, so IgG is high from very early in the illness while IgM may be lower or delayed. The combination of both IgM and IgG positive early in an acute febrile illness therefore indicates a secondary infection.",
      "This distinction matters clinically. Secondary dengue carries a substantially higher risk of severe disease \u2014 plasma leakage, haemorrhage and shock \u2014 through antibody-dependent enhancement, in which antibodies from the first infection bind but fail to neutralise the new serotype and instead facilitate viral entry into cells. In urban India, where most adults have had dengue before, secondary infection is the norm rather than the exception."
    ],
    "whyImportant": [
      "Evaluates key clinical parameters for Dengue IgM and IgG Antibodies.",
      "Conducted at NABL Accredited super speciality laboratory (MC-6849).",
      "Digital PDF report delivered directly to your WhatsApp & Email."
    ],
    "faqs": [
      {
        "question": "When does dengue IgM become positive?",
        "answer": "From around day 5 of fever, peaking at days 10 to 14 and persisting for two to three months. Testing IgM before day 5 commonly gives a false negative, which is why NS1 antigen is the correct test in the first five days."
      },
      {
        "question": "What does dengue IgM positive and IgG positive mean?",
        "answer": "Both positive early in an acute febrile illness indicates a secondary dengue infection \u2014 a repeat infection with a different serotype. This carries a higher risk of severe disease through antibody-dependent enhancement, and warrants closer monitoring of platelet count, haematocrit and warning signs."
      },
      {
        "question": "What does dengue IgG positive alone mean?",
        "answer": "In a person who is well, it simply indicates past dengue exposure at some point in the past and requires no action. In an acutely febrile person early in the illness, IgG alone can indicate an early secondary infection before IgM has risen, so the clinical picture matters."
      },
      {
        "question": "Why is a second dengue infection more dangerous?",
        "answer": "Because of antibody-dependent enhancement. Antibodies from the first infection bind to the new serotype but fail to neutralise it, and instead help the virus enter cells more efficiently. This drives greater plasma leakage and a higher risk of haemorrhage and shock."
      },
      {
        "question": "Can dengue IgM be falsely positive?",
        "answer": "Yes. Dengue IgM cross-reacts with other flaviviruses including Zika, Japanese encephalitis and West Nile virus, and with recent Japanese encephalitis or yellow fever vaccination. In a region where these circulate, a positive IgM should be read alongside the clinical picture rather than taken as definitive."
      },
      {
        "question": "Which dengue test should I do on day 6 of fever?",
        "answer": "Both NS1 and IgM. Day 5 to 7 is the transition period where NS1 sensitivity is falling and IgM is just becoming detectable, so testing both maximises the chance of a diagnosis. A complete blood count should accompany either."
      },
      {
        "question": "How long does dengue IgM stay positive?",
        "answer": "Two to three months after infection. This means a positive IgM in someone with a new fever may reflect a dengue episode from the recent past rather than the current illness, which is worth remembering before attributing every subsequent fever to dengue."
      },
      {
        "question": "Do I need to fast for a dengue antibody test?",
        "answer": "No, fasting is not required and the sample can be taken at any time. What matters is the day of illness \u2014 IgM before day 5 is likely to be falsely negative \u2014 and having a complete blood count done alongside."
      },
      {
        "question": "If my dengue IgG is positive, am I immune?",
        "answer": "Only to the serotype you were infected with. There are four dengue serotypes, and immunity to one does not protect against the other three. In fact a second infection with a different serotype carries a higher risk of severe disease, so past infection is not protection in any reassuring sense."
      },
      {
        "question": "What if all my dengue tests are negative but I still have fever?",
        "answer": "Dengue is only one of several causes of acute fever in India. Malaria, typhoid, chikungunya, leptospirosis, scrub typhus, urinary infection and respiratory infection all present similarly and need to be considered. Persistent fever beyond five days without a diagnosis warrants proper medical review rather than more repeat testing."
      }
    ],
