    "faqs": [
      {
        "question": "What does HBsAg positive mean?",
        "answer": "It means the hepatitis B virus is present in your blood and you have an active infection. It does not by itself say whether the infection is acute or chronic, how much virus is present, or whether your liver is damaged \u2014 all of which require further tests including anti-HBc IgM, HBV DNA, liver function and imaging."
      },
      {
        "question": "What is the difference between acute and chronic hepatitis B?",
        "answer": "If HBsAg clears within six months, the infection was acute and has resolved, usually leaving lifelong immunity. If HBsAg persists beyond six months, the infection is chronic. The risk of chronicity depends on age at infection \u2014 over 90% for newborns, under 5% for adults."
      },
      {
        "question": "What tests should follow a positive HBsAg?",
        "answer": "HBeAg and anti-HBe, HBV DNA viral load, liver function tests, complete blood count, prothrombin time, alpha-fetoprotein, and an abdominal ultrasound with fibrosis assessment. Household and sexual contacts should also be tested and vaccinated if not already immune."
      },
      {
        "question": "Does everyone with chronic hepatitis B need treatment?",
        "answer": "No. The decision depends on the HBV DNA level, liver enzymes, fibrosis stage, age and family history of liver cancer, and is made by a hepatologist. Many people are in a low-replication phase requiring monitoring rather than antivirals \u2014 but everyone needs six-monthly surveillance for liver cancer."
      },
      {
        "question": "Can hepatitis B be cured?",
        "answer": "Chronic hepatitis B can usually be controlled but not eradicated with current treatment. Antiviral drugs suppress the virus effectively, reduce liver damage and substantially lower the risk of cirrhosis and liver cancer, but the virus persists in liver cells. Treatment is often long-term, and stopping requires specialist guidance."
      },
      {
        "question": "What does anti-HBs positive with HBsAg negative mean?",
        "answer": "It means you are immune. If anti-HBc is also negative, the immunity came from vaccination. If anti-HBc is positive, it came from a past infection you have cleared. Either way you are protected and not infectious. An anti-HBs level above 10 mIU/mL is considered protective."
      },
      {
        "question": "Should my family be tested if I am HBsAg positive?",
        "answer": "Yes, all household and sexual contacts should be tested for HBsAg, anti-HBs and anti-HBc, and vaccinated if not already immune. Hepatitis B transmits through blood and body fluids, including within households through shared razors and toothbrushes, and vaccination is highly effective at preventing it."
      },
      {
        "question": "Why is hepatitis B testing needed before chemotherapy?",
        "answer": "Because immunosuppression can cause dormant hepatitis B to reactivate, sometimes with fatal liver failure. This is entirely preventable with prophylactic antiviral treatment, but only if the infection is known about beforehand. Screening before chemotherapy, rituximab or any significant immunosuppression is essential."
      },
      {
        "question": "Do I need to fast for a hepatitis B test?",
        "answer": "No, fasting is not required and the sample can be taken at any time. Pre- and post-test counselling should accompany the test, given the family, social and occupational implications of a positive result."
      },
      {
        "question": "Can a baby be protected if the mother is HBsAg positive?",
        "answer": "Yes, in the great majority of cases. Giving the newborn hepatitis B immunoglobulin and the first vaccine dose within 12 hours of birth prevents transmission in over 90% of cases, and maternal antiviral treatment in late pregnancy reduces the risk further when the viral load is high. This is why antenatal hepatitis B screening matters."
      }
    ],
