      "The confirmatory test is HCV RNA by PCR, which detects the virus itself. A positive anti-HCV with a positive HCV RNA means current infection requiring treatment. A positive anti-HCV with an undetectable HCV RNA means past infection, either cleared spontaneously or successfully treated, with no ongoing disease.",
      "The treatment story has changed completely. Direct-acting antiviral drugs cure over 95% of people with 8 to 12 weeks of well-tolerated oral tablets, and generic versions are available in India at a fraction of the original cost. This makes case finding genuinely worthwhile \u2014 a disease that once meant slow progression to cirrhosis is now, in most cases, curable. India has a national viral hepatitis control programme providing free treatment."
