      "The legal framework in India is clear. The HIV and AIDS (Prevention and Control) Act, 2017 requires informed consent before testing, mandates pre- and post-test counselling, and prohibits disclosure of a person's HIV status without their consent. Testing without consent, or disclosing status to family or employers, is unlawful. QXL Diagnostics follows NACO guidelines on consent, counselling and confidentiality for all HIV testing."
